/** Hero -- generated by the template lab from Figma node 538:38996
 *  (Hero). Everything is drawn from the board itself
 *  (FigmaLayers); the slots below are what a designer edits, each in its
 *  board place and stacking order:
 *    copy tied to the brief -- offer, lead, urgency;
 *    board copy, editable -- cta/shop-save, select-sale-styles;
 *    photos -- image/photo; brand slots -- none.
 *  Text contracts come from each board layer (boardFit). NUDGE (./nudges.ts)
 *  holds the fix loop's per-layer corrections to Figma's render. */
import type { SheetAsset } from '../../../../../sheet/types';
import { Ground } from '../../../../../edit/Editable';
import { Picture } from '../../../../../edit/Picture';
import { ZONE_LIST, photoFor } from '../../../../../model/compose';
import { FigmaLayers, FigmaText, FigmaStroke, FigmaMark, type Slot } from '../../../../../render/figma/FigmaLayers';
import { cropOf, type FigmaLayout } from '../../../../../render/figma/layout';
import board from './layout.json';
import { NUDGE } from './nudges';

/** Which board layer each editable layer is, by the part of its id after the asset's. */
export const HERO_538_38996_FIGMA = {
  "cta/shop-save": "538:38999", // text: Shop & Save
  "offer": "538:39003", // offer: 20% OFF
  "select-sale-styles": "538:39004", // text: Select sale styles
  "lead": "538:39005", // lead: EXTRA
  "urgency": "538:39007", // urgency: FINAL HOURS!
  "cta/cta": "538:38998", // pill: CTA
  "art/vector-742": "538:39006", // graphic: Vector 742
  "image/photo": "538:38997", // photo: image 3736
} as const;

export function Hero_538_38996({ asset }: { asset: SheetAsset }) {
  const layout = board as unknown as FigmaLayout, id = asset.id;
  const zone = ZONE_LIST.find(z => z.id === asset.media.photo) ?? photoFor('hike', 0);
  const slots: Record<string, Slot> = {
    [HERO_538_38996_FIGMA["cta/shop-save"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/cta/shop-save`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [HERO_538_38996_FIGMA["offer"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/offer`} contract="lab.offer" layout={layout}
      text={asset.copy.offer || l.text!.chars} />,
    [HERO_538_38996_FIGMA["select-sale-styles"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/select-sale-styles`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [HERO_538_38996_FIGMA["lead"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/lead`} contract="lab.lead" layout={layout}
      text={asset.copy.lead ? (l.text!.chars.includes('\u2028') ? asset.copy.lead.replace(/\s+/, '\n') : asset.copy.lead) : l.text!.chars} />,
    [HERO_538_38996_FIGMA["urgency"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/urgency`} contract="lab.urgency" layout={layout}
      text={asset.copy.urgency || asset.copy.marquee || asset.copy.eyebrow || l.text!.chars} />,
    [HERO_538_38996_FIGMA["cta/cta"]]: (l, box, _n, board) => <>
      <FigmaMark l={l} box={box} id={`${id}/cta/cta/mark`} src="/graphics/named-sale-pill-528x120-c8636n.svg" fill="#F14222" layout={layout} />
      {board({ bare: true })}
    </>,
    [HERO_538_38996_FIGMA["art/vector-742"]]: (l, box) => <FigmaMark l={l} box={box} id={`${id}/art/vector-742/mark`} src="/graphics/named-sale-vector-742-o4us53.svg"
      fill="#F14222" layout={layout} />,
    [HERO_538_38996_FIGMA["image/photo"]]: (l, box) => {
      const img = l.images?.[0] && layout.assets?.[l.images[0].ref];
      const crop = img && l.crop ? cropOf(l.crop, [l.w, l.h], [img.w, img.h]) : undefined;
      // The board's fade, kept for whatever photo fills the slot.
      const fade = l.images?.[0]?.opacity;
      return <>
        <Picture id={`${id}/image/photo`} zone={zone} initialSrc={img?.src} slot
          focus={crop?.focus} initialScale={crop?.initialScale} initialRotate={crop?.rotate} initialCrop={l.crop}
          style={{ ...box, overflow: 'hidden', borderRadius: l.radius, clipPath: l.path ? `path("${l.path}")` : undefined, opacity: fade ?? box.opacity }} />
        <FigmaStroke l={l} box={box} />
      </>;
    },
  };
  const [w, h] = layout.size;
  // data-figma-compiled: the studio's Figma export reads a compiled board's way (toLayers).
  return <Ground id={`${id}/fill`} className="sheet" data-figma-compiled="" style={{ width: w, height: h, position: 'relative', overflow: 'hidden', background: '#fff' }}>
    <FigmaLayers layout={layout} slots={slots} nudges={NUDGE} />
  </Ground>;
}
